INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('The real-life value of Community Enhancement funding', 'community-enhancement-funding-pullough-offaly', '<div>
<div>
<p>In 2018, more than 3,000 projects around the country got a share of €12.5 million in funding through the <a href="https://drcd.gov.ie" target="_blank" rel="nofollow noopener noreferrer">Department of Rural and Community Development</a>’s <a href="https://drcd.gov.ie/community/community-enhancement-programme/" target="_blank" rel="nofollow noopener noreferrer">Community Enhancement Programme</a> (CEP), which provides small grants to disadvantaged communities.</p>
<p>A closer look at that €12.5m allows us to move beyond the broad strokes to see a picture of how CEP changes communities on a basic level.</p>
<p>In Co Offaly, for example, 115 groups received community enhancement funding. Boil that down to community level and we see that Pullough, the small parish <a href="https://changingireland.ie/index.php/2019/03/06/pullough-community-shop/" target="_blank" rel="noopener noreferrer">featured on the <em>Changing Ireland </em>Feb-March cover</a>, pulled in €2,000.</p>
<h4><strong>How does that €2,000 translate to community-level improvements? </strong></h4>
<p>Community groups often fundraise to get much needed resources for local development, but it can be a struggle to raise enough to cover everything. The projects that Pullough sought funds for are a great example of the kind of needs for which CEP is invaluable.</p>
<p>Four groups from Pullough received €500 each:</p>
<p>Pullough Community Action Group used their €500 on a laptop and printer.</p>
<p>Pullough Resident’s Development Association spent theirs on IT equipment that would be used by community groups for training.</p>
<p>Pullough Resident’s Development Association and Pullough Tidy Towns got together to spend another €500 on works to make the canal area of the village more attractive.</p>
<p>The €500 awarded to Dernagun Residents Association went on a lawnmower and a hedge cutter.</p>
<p><em>The full list of projects supported nationally can be found </em><a href="https://www.gov.ie/en/organisation/department-of-rural-and-community-development/" target="_blank" rel="nofollow noopener noreferrer"><em>on the Department’s website</em></a><em>.</em></p>
<p><strong><em>Interested in reading more about the state of Ireland’s community development sector? Check out our </em></strong><a href="https://bit.ly/Issue63-FebMar19" target="_blank" rel="nofollow noopener noreferrer"><strong><em>latest issue</em></strong></a><strong><em>.</em></strong></p>
<p><em><a href="https://www.rawpixel.com/image/385522/free-photo-image-money-finance-investment" target="_blank" rel="noopener noreferrer">Main photo</a>: </em><a href="https://www.rawpixel.com/ake/showcase" target="_blank" rel="nofollow noopener noreferrer"><em>Ake</em></a><em>/</em><a href="https://www.rawpixel.com/" target="_blank" rel="nofollow noopener noreferrer"><em>Rawpixel</em></a></p>
</div>
</div>
<div></div>', 'When it comes to large funding programmes, it can be hard to see beyond the big numbers to the actual impact they make on communities. It’s only when you look at the nitty gritty that their true value reveals itself.', 'https://changingireland.ie/wp-content/uploads/2019/08/image-from-rawpixel-id-385522-jpeg.jpg', 'Money jar and growing seed', '[{"slug":"funding-programmes","title":"Funding Programmes"}]', '[{"slug":"community-development","title":"community development"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"funding","title":"funding"},{"slug":"offaly","title":"Offaly"}]', '', 247383, 1, '2019-04-23T12:47:03Z', '2019-09-13T13:19:06Z', '2019-04-23T12:47:03Z')
