INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('How Community Futures built one village’s community space', 'community-futures-straide-mayo', '<p>By this summer, the Co Mayo village of Straide will have the equivalent of a brand-new multipurpose hall. The Michael Davitt Community Hall – closed now for some time – is to be resurrected.</p>
<p>When finished, the refurbished hall will have new windows, a new heating system, a kitchen, office space and toilets.</p>
<p>Carol Reading, vicechair of Straide Community Development Group, said: “We’re looking forward. We’re going to be able to use it for indoor football, badminton and birthday parties. We also aim to make it available for community events like month’s minds.”</p>
<p>The group gives full credit for the hall’s revitalisation to <a href="https://www.mayococo.ie/en/Services/CommunityEngagement/CommunityandIntegratedDevelopment/MayoCommunityFutures/" target="_blank" rel="nofollow noopener noreferrer">Community Futures</a>, a county council-led process that has helped communities across Mayo to actively plan and deliver much needed projects.</p>
<p>While funding support usually makes all the difference to a project’s success, in this case it was Mayo County Council’s community development approach helping the Straide community see their priorities clearly.</p>
<p>The renewal works have been years in the planning, soaking up many hours of volunteer involvement and costing €167,000. But Straide stuck with it in spite of the obstacles, with help coming from LEADER and from the diaspora’s fundraising support.</p>
<p>“We have had families from the UK, America – and obviously Straide – contribute to the fundraising,” Carol said.</p>
<p>Straide Community Development Group chairperson Derek Murphy welcomed the LEADER funding: “There was no money spent on the hall since the 1980s and it needed an upgrade.”</p>
<figure aria-describedby="caption-attachment-247389"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2019/04/0-300x200.jpeg" alt="Straide Community Development Group chairperson Derek Murphy and vice-chairperson Carol Reading with group member Kate O''Hara" width="600" height="400" srcset="https://changingireland.ie/wp-content/uploads/2019/04/0-300x200.jpeg 300w, https://changingireland.ie/wp-content/uploads/2019/04/0-768x512.jpeg 768w, https://changingireland.ie/wp-content/uploads/2019/04/0-1024x683.jpeg 1024w, https://changingireland.ie/wp-content/uploads/2019/04/0-1080x720.jpeg 1080w" sizes="(max-width: 600px) 100vw, 600px" /><figcaption><em>Straide Community Development Group chairperson Derek Murphy and vice-chairperson Carol Reading with group member Kate O&#8217;Hara. Photo: Changing Ireland.</em></figcaption></figure>
<h4><strong>Looking to the Futures</strong></h4>
<p>Mayo Community Futures is a bottom-up, community-led process that gives all members of a community the opportunity to feed into an action plan for development. It aims to:</p>
<p>· help communities to prepare Community Action Plans,</p>
<p>· encourage more people to become active in their communities,</p>
<p>· strengthen and develop local community organisations,</p>
<p>· enable communities to identify and progress priority projects, and</p>
<p>· enable communities to effectively represent their interests at local, county and national level.</p>
<p>Kate O’Hara, secretary of Straide Community Development Group, said: “We got every group in Straide involved in the Mayo Community Futures process. It’s a great system; it gets all stakeholders involved.”</p>
<p>“Out of that, we created our development group and came up with an action plan. Mayo County Council run Community Futures, and it got us to do a household survey. We found out what the priorities were and came up with an action plan.”</p>
<p>“There are 60 children in the local primary school and they have no ‘halla’, no facilities, so the hall refurbishment was vital. We have a church, a pub and the museum in Straide, and we got to the point where the community needed space,” she said.</p>
<p>The Community Futures approach was introduced in 2006, and 30 Mayo communities have participated in it to date.</p>
<p>The process is administered by Mayo County Council and takes about six months to complete.</p>
<p>The main tools for encouraging participation are household surveys, stakeholder interviews, compiling a community profile, and organising a Community Day event.</p>
<p><strong><em>Interested in reading more about the state of Ireland’s community development sector? Check out our </em></strong><a href="https://l.facebook.com/l.php?u=https%3A%2F%2Fbit.ly%2FIssue63-FebMar19%3Ffbclid%3DIwAR3-fvq4coDZOlY5jO86jL-qGSfpw8S2zAAh1wwhAxBpTMWHHpnW8sOqF18&amp;h=AT3CAZx5Sgp6dnM0xYvhQIIpCRrQw9XRXcwxhzMF3jRQ53DY6Kyw3tOOh3k6H_5YuDkXKu1M5YhHi79zvY8_ffYlxLFX0RAYq6uSwlYp8bhMixiG92Sdc8aZQf-9af0xI_8qOVUM3n0" target="_blank" rel="nofollow noopener noreferrer"><strong><em>latest issue</em></strong></a><strong><em>.</em></strong></p>', 'As Straide Community Development Group prepares to reopen the Mayo village’s hall, they credit a process called Community Futures for making it possible.', 'https://changingireland.ie/wp-content/uploads/2019/08/0-1-1.jpeg', 'Minister Michael Ring TD pictured with members of the Straide community and Community Development Group', '[{"slug":"development-work","title":"Development Work"}]', '[{"slug":"community-development","title":"community development"},{"slug":"funding","title":"funding"},{"slug":"leader","title":"LEADER"},{"slug":"mayo","title":"Mayo"}]', '', 247386, 1, '2019-04-19T13:03:09Z', '2019-09-13T13:25:23Z', '2019-04-19T13:03:09Z')
