INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('The Big Hello: How can you get to know the neighbours?', 'the-big-hello', '<p>Over the May bank holiday weekend (from 4–6 May), groups across Ireland will be taking part in the country’s first ever National Community Weekend. ‘<a href="https://www.gov.ie/en/news/038265-the-big-hello-national-community-weekend-2019/" target="_blank" rel="nofollow noopener noreferrer">The Big Hello!</a>’ will aim to strengthen community ties and help tackle the problem of social isolation.</p>
<p>Michael Ring, Minister for Rural and Community Development, is encouraging communities to come up with ideas to make it a success.</p>
<p>“National Community Weekend belongs to everyone,” said Minister Ring. “We don’t want to tell communities what they should do – the events will be very much driven by communities.”</p>
<p>The Department of Rural and Community Development hopes that at least 1,000 local events will be held throughout Ireland, and each of the 31 local authorities have been allocated €10,000 to support initiatives in their areas.</p>
<p>There are good reasons to hold a community weekend. People are busier than before, digitally distracted and often do not know their neighbours.</p>
<p>This nationwide event will present an opportunity to involve or say ‘hello’ to those among us who are living alone or isolated.</p>
<p>“The weekend is a chance for people to foster a sense of helping each other,” said Minister Ring. He said he too does not see as much of his own neighbours as he would like – as he is often away on government business – and he looks forward to the weekend.</p>
<p>Events could include themes around sport, history, baking or anything that will help neighbours to come together. It could be as simple as neighbours meeting up for a cup of tea and a chat.</p>
<p>Those interested in organising an event in their community can contact their local authority for an information pack and funding.</p>
<p>Share your ideas for celebrations with us and we’ll pass your brainwaves on via social media.</p>
<h4><strong>How does the rest of the world celebrate community?</strong></h4>
<p>National community days and weekends are uncommon, with seemingly few countries holding events of this type.</p>
<p>The Caribbean island of Dominica, with its population of just over 73,000 people, holds a National Day of Community Service every November, during which people engage in ‘Tidy Towns’ type activities and acts of kindness.</p>
<p>Perhaps Ireland will set a new trend? If you know of other countries that hold events to honour and support communities, please let us know.</p>
<p><strong><em>Interested in reading more about the state of Ireland’s community development sector? Check out our </em></strong><a href="https://bit.ly/Issue63-FebMar19" target="_blank" rel="nofollow noopener noreferrer"><strong><em>latest issue</em></strong></a><strong><em>.</em></strong></p>
<p><em><a href="https://pixabay.com/photos/conversation-talking-young-people-1177860/" target="_blank" rel="noopener noreferrer">Main </a><a href="https://pixabay.com/" target="_blank" rel="nofollow noopener noreferrer">photo: </a><a href="https://pixabay.com/users/angelladagenhart0-738564/" target="_blank" rel="nofollow noopener noreferrer">angelladagenhart0</a><a href="https://pixabay.com/" target="_blank" rel="nofollow noopener noreferrer">/</a><a href="https://pixabay.com/" target="_blank" rel="nofollow noopener noreferrer">Pixabay</a></em></p>', 'Wish you knew more about the people living next door? Here’s your opportunity…', 'https://changingireland.ie/wp-content/uploads/2019/08/conversation-1177860_1280.jpg', 'Community members catch up', '[{"slug":"initiatives","title":"Initiatives"}]', '[{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"events","title":"events"},{"slug":"local-authorities","title":"local authorities"}]', '', 247450, 1, '2019-03-12T15:10:52Z', '2019-09-13T13:52:22Z', '2019-03-12T15:10:52Z')
