INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('No job? No problem: A Terenure crash course in entrepreneurship', 'entrepreneurship-training-terenure-dublin', '<p>Last summer, <a href="https://www.terenure-enterprise.ie/" target="_blank" rel="nofollow noopener noreferrer">Terenure Enterprise Centre</a> ran a training course – Destination Innovation – for young entrepreneurs. It gave participants a sense that they can be their own bosses and create their own jobs. It was a revelation for some of them.</p>
<p>We hope to replicate the course later this year.</p>
<p>The project was started after we were approached by the Walkinstown Association for People with an Intellectual Disability (Walk).</p>
<p><a href="https://www.walk.ie/" target="_blank" rel="nofollow noopener noreferrer">Walk</a>’s team of employment staff knew that young people with disabilities have difficulties finding paid and meaningful employment, and the labour market in Ireland is all but closed to individuals with intellectual disabilities. When it came to such bright and brilliant individuals, the association felt that supporting them in creating their own businesses could be a solution to the issue.</p>
<p>We then designed a hands-on entrepreneurial training course to meet the needs of the group of young people in an accessible way.</p>
<p>The course was a success because we were very flexible in our approach and did things with the participants that they were passionate about. We were following their lead.</p>
<h4><strong>How did it work?</strong></h4>
<p>Five young people took part and the training took place over four sessions, each lasting two hours. The participants drew on their talents, passions and skills to develop a variety of business ideas. They proposed a handmade jewellery business and an artwork business, as well as working as a band manager, a DJ and a beautician.</p>
<p>Each training session was filled with practical activities and tailored to the needs of the learners, as each of them was at a different stage of creating their products or services. Some participants were already testing their ideas, while others were building a body of work or refining their skills to start their business.</p>
<p>The students had a chance to discuss their business ideas and decide what resources they needed to make it a reality. One of them (the DJ) turned the work he was doing voluntarily into paid work.</p>
<p>The course also focused on future clients, making themselves and their businesses visible online and offline, and improving their digital skills. All participants felt the course was a valuable experience.</p>
<p>The project finished with a showcase event in October – organised by Walk – where the young entrepreneurs presented their businesses and won over new clients.</p>
<p>The course was free for participants and was funded through <a href="https://www.dccae.gov.ie/en-ie/communications/topics/Digital-Strategy/getting-citizens-online/Pages/Citizens-and-Training.aspx" target="_blank" rel="nofollow noopener noreferrer">Getting Citizens Online</a>.</p>
<p><strong>For more information on the course, and to find out how you can replicate it in your local community, contact Vasilena Vasileva at </strong><a href="https://www.terenure-enterprise.ie/" target="_blank" rel="nofollow noopener noreferrer"><strong>Terenure Enterprise Centre</strong></a><strong>.</strong></p>
<p><strong><em>Interested in reading more about the state of Ireland’s community development sector? Check out our </em></strong><a href="https://bit.ly/Issue63-FebMar19" target="_blank" rel="nofollow noopener noreferrer"><strong><em>latest issue</em></strong></a><strong><em>. </em></strong></p>', 'Often, it can be the more vulnerable people in our communities who have the most difficulty finding ways to be self-sustaining. Here, Terenure Enterprise Centre enterprise support officer Vasilena Vasileva explains what they did with Walk to change that.', 'https://changingireland.ie/wp-content/uploads/2019/08/terenure-enterprise.jpeg', 'Participants on Terenure Enterprise Centre''s Destination Innovation', '[{"slug":"initiatives","title":"Initiatives"}]', '[{"slug":"disability-supports","title":"disability supports"},{"slug":"dublin","title":"Dublin"},{"slug":"employment-supports","title":"employment supports"},{"slug":"guest-column","title":"Guest Column"},{"slug":"training","title":"training"}]', '', 247467, 1, '2019-03-04T16:20:24Z', '2019-09-13T13:56:41Z', '2019-03-04T16:20:24Z')
