INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('I Am Traveller: Talking history, heritage and social inclusion', 'i-am-traveller-national-museum-country-life', '<p>This Saturday afternoon (23 February, 2019), the public is invited to the <a href="https://www.museum.ie/Country-Life" target="_blank" rel="noopener noreferrer">National Museum of Ireland – Country Life</a>’s ‘I Am Traveller: Our Histories and Heritage’, a panel discussion focusing on Traveller culture and tradition.</p>
<p>A strong panel has been assembled for the event, with Senator Colette Kelleher chairing the three-hour event (2-5pm) and Brigid Carmody, Hugh Friel, Michael McDonagh, Mary Collins and Oein DeBhairduin sharing their insights on traditional and contemporary Traveller culture and community initiatives.</p>
<p>“The panel discussion will examine culture and heritage and good social inclusion practices,” said museum curator Rosa Meehan. “We hope it will be of particular interest to Social Inclusion Community Activation Programme (SICAP) teams who work with and support the Traveller community.”</p>
<p>Representatives of Traveller groups from across the country – including Cork, Donegal, Meath, Mayo and Dublin – plan to attend the discussion.</p>
<p>According to organisers, tickets are going fast and only a very limited number of spaces remain available – booking, they say, is essential.</p>
<p>The panel discussion is one of a number of events taking place as part of the <a href="https://www.museum.ie/Country-Life/Exhibitions/Previous-Exhibitions/Travellers-Journey" target="_blank" rel="noopener noreferrer">Travellers’ Journey exhibition</a>, which will be on show in the museum until May.</p>
<p>The exhibition shows the rich culture, traditions and crafts of the Traveller community in the west of Ireland. It has been curated in partnership with the Western Regional Traveller Health Network.</p>
<p><em>To book a place at the talk, email <a href="mailto:educationtph@museum.ie" target="_blank" rel="noopener noreferrer">educationtph@museum.ie</a>, or phone <a href="tel:+353949031751">094 903 1751</a>.</em></p>', 'Social inclusion policies don’t always reach everyone that needs them. How can that be addressed in the Traveller community?', 'https://changingireland.ie/wp-content/uploads/2019/08/Screenshot-2019-08-15-at-18.03.03.jpg', 'Traveller child at play', '[{"slug":"inclusion","title":"Inclusion"}]', '[{"slug":"art-culture","title":"art and culture"},{"slug":"cultures","title":"cultures"},{"slug":"events","title":"events"},{"slug":"mayo","title":"Mayo"},{"slug":"social-inclusion","title":"social inclusion"},{"slug":"travellers","title":"Travellers"}]', '', 247480, 1, '2019-02-20T17:52:47Z', '2019-09-13T14:00:55Z', '2019-02-20T17:52:47Z')
